import re
import pytest
from pathlib import Path

# Path to the file generated by the LLM
PY_FILE = Path(__file__).resolve().parents[1] / "service_state.py"

@pytest.fixture
def code():
    with open(PY_FILE, 'r') as f:
        return f.read()

def test_ros2_client_creation(code):
    """Verify that the ROS2 client is initialized using the node handle."""
    pattern = r"self\.node\.create_client\s*\(\s*self\._service_spec\s*,\s*self\._service_name\s*\)"
    assert re.search(pattern, code), "Failed to find ROS2 create_client initialization."

def test_service_ready_check(code):
    """Verify the migration of wait_for_service to ROS2 API."""
    pattern = r"self\._proxy\.(?:service_is_ready|wait_for_service)\s*\("
    assert re.search(pattern, code), "Missing ROS2 service readiness check (service_is_ready or wait_for_service)."

def test_preemption_logic_retention(code):
    """Ensure the state machine still checks for SMACH preemption during the wait loop."""
    pattern = r"while.*:\s*(?:.|\n)*?self\.preempt_requested\s*\(\s*\)"
    assert re.search(pattern, code), "Preemption check logic was lost during migration."

def test_ros2_logging_api(code):
    """Verify that ROS1 rospy.log* calls are replaced with ROS2 node.get_logger()."""
    assert "rospy.log" not in code, "Legacy rospy logging found. Use self.node.get_logger()."
    pattern = r"self\.node\.get_logger\s*\(\s*\)\.(?:info|warn|error|debug)"
    assert re.search(pattern, code), "ROS2 logging calls (get_logger) not found."

def test_service_call_execution(code):
    """Verify the service call execution using the proxy client."""
    # Matches both .call(req) and .call_async(req)
    pattern = r"self\._proxy\.(?:call|call_async)\s*\("
    assert re.search(pattern, code), "Service call execution logic is missing."

def test_userdata_request_mapping(code):
    """Verify that the logic for mapping userdata slots to the request is preserved."""
    pattern = r"setattr\s*\(\s*self\._request\s*,\s*key\s*,\s*ud\[key\]\s*\)"
    assert re.search(pattern, code), "Request slot mapping from userdata is missing."

def test_request_callback_execution(code):
    """Verify that the user-provided request callback is still invoked."""
    pattern = r"self\._request_cb\s*\("
    assert re.search(pattern, code), "Request callback execution logic is missing."

def test_no_legacy_ros1_symbols(code):
    """Ensure no ROS1-specific library symbols remain in the code."""
    legacy_symbols = ["rospy\.ServiceProxy", "rospy\.init_node", "rospy\.Time"]
    for symbol in legacy_symbols:
        assert not re.search(symbol, code), f"Legacy ROS1 symbol '{symbol}' detected."